<script lang="ts">import type {StageSegment} from '../generated/StageSegment';import {colors} from '../charts';let {segments}:{segments:StageSegment[]}=$props();const names=['Awake','REM','Light','Deep'];const palette:Record<string,string>={awake:colors.awake,rem:colors.rem,light:colors.light,deep:colors.deep};let total=$derived(Math.max(1,...segments.map(s=>s.startMin+s.minutes)));</script><svg viewBox="0 0 326 142" class="plot" aria-label="Sleep stages over the night">{#each names as name,i}<text x="0" y={i*30+19} fill="#69728A" font-size="11" font-weight="600">{name}</text><line x1="46" x2="326" y1={i*30+15} y2={i*30+15} stroke="rgba(255,255,255,.05)"/>{/each}{#each segments as s,i}{@const lane=names.indexOf(s.stage==='rem'?'REM':s.stage[0].toUpperCase()+s.stage.slice(1))}{@const x=46+s.startMin/total*280}{#if i>0}{@const prev=segments[i-1]}<line x1={x} x2={x} y1={names.indexOf(prev.stage==='rem'?'REM':prev.stage[0].toUpperCase()+prev.stage.slice(1))*30+15} y2={lane*30+15} stroke="rgba(255,255,255,.22)"/>{/if}<rect x={x} y={lane*30+4} width={Math.max(2,s.minutes/total*280)} height="22" rx="5" fill={palette[s.stage]}/>{/each}{#each ['23:00','01:00','03:00','05:00'] as t,i}<text x={50+i*80} y="139" fill="#69728A" font-size="11" text-anchor="middle">{t}</text>{/each}</svg><style>.plot{display:block;width:100%}</style>